/*
 c = b + 1
                d = a_c 
                where
                a  ∈ ℝ^3
                b  ∈ ℤ index
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    int c;
    DT d;

    heartlib(
        const Eigen::Matrix<double, 3, 1> & a,
        const int & b)
    {

        // c = b + 1
        c = b + 1;
        // d = a_c
        d = a[c];
    }
};

