outputs.matlab:
function output = heartlib(a, b)
% output = heartlib(a, b)
%
%     c = b + 1
%                    d = a_c 
%                    where
%                    a  ∈ ℝ^3
%                    b  ∈ ℤ index
    a = reshape(a,[],1);

    assert( numel(a) == 3 );
    assert(numel(b) == 1);

    % c = b + 1

    c = b + 1;
    % d = a_c

    d = a(c);
    output.c = c;
    output.d = d;
end

